<script setup>
import {FilePenLine} from '@lucide/vue'
import {inject,computed,onMounted,onBeforeUnmount,ref} from 'vue'
import {useRoute,onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router'
import {api} from '../api'
import ReportModeFields from '../components/ReportModeFields.vue'
import ReportEvaluation from '../components/ReportEvaluation.vue'
import FilePreview from '../components/FilePreview.vue'
import {experience,setCourseExperience} from '../composables/experience'
import {formatDate,toLocalInput,toUtc} from '../utils/assignments'
const roster=ref([])
const selectedCourse=inject('selectedCourse',null)
const route=useRoute(),report=ref(null),submissions=ref([]),error=ref(''),notice=ref(''),busy=ref(false),file=ref(null),editing=ref(false),form=ref(null),baselines=ref({})
const staff=computed(()=>['teacher','ta'].includes(report.value?.courseRole))
const base=`/reports/${route.params.reportId}`
function changed(s){const old=baselines.value[s.id];return old && (s.score!==old.score || JSON.stringify(s.members)!==old.members || s.feedback!==old.feedback)}
const gradeDirty=computed(()=>staff.value && submissions.value.some(changed))
async function load(savedId=null){report.value=await api(base);if(route.params.courseId && report.value.courseId!==route.params.courseId){report.value=null;throw new Error('此評量不屬於指定課程。')}setCourseExperience(staff.value||report.value.isPractice);roster.value=await api(base+'/roster');const fresh=staff.value && selectedCourse?.value?.taRestrictions?.includes('grading')?[]:await api(base+'/submissions');submissions.value=fresh.map(s=>{const old=submissions.value.find(x=>x.id===s.id);if(s.id!==savedId && old && changed(old))return old;baselines.value[s.id]={score:s.score,feedback:s.feedback,members:JSON.stringify(s.members)};return s})}

async function run(action){busy.value=true;error.value='';notice.value='';try{await action()}catch(e){error.value=e.message}finally{busy.value=false}}
async function transition(action){if(!confirm(action==='publish'?'發布後學生可繳交，作業內容會鎖定。確定發布？':'確定關閉繳交？'))return;await run(async()=>{await api(base+'/'+action,{method:'POST'});await load()})}
function edit(){form.value={...report.value,groupIds:[...report.value.groupIds],dimensions:[...report.value.dimensions],opensAt:toLocalInput(report.value.opensAt),dueAt:toLocalInput(report.value.dueAt),expectedVersion:report.value.version};editing.value=true}
async function save(){await run(async()=>{await api(base,{method:'PUT',body:{...form.value,opensAt:toUtc(form.value.opensAt),dueAt:toUtc(form.value.dueAt)}});editing.value=false;await load();notice.value='PDF 作業草稿已儲存。'})}
async function submit(){if(!confirm('確定將這份 PDF 正式繳交？'))return;await run(async()=>{const body=new FormData();body.append('file',file.value);await api(base+'/submit',{method:'POST',body});file.value=null;await load();notice.value='PDF 報告已繳交。'})}
async function download(s,previous=null){await run(async()=>{const blob=await api(`${base}/submissions/${s.id}/download`+(previous?'?revision='+previous.revision:''),{method:'POST',download:true});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=previous?.fileName||s.fileName;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)})}
async function returnFile(s){if(confirm('退回此版本供修改？'))await run(async()=>{await api(base+'/submissions/'+s.id+'/return?version='+s.version,{method:'POST'});await load(s.id)})}
async function grade(s,publish=false){await run(async()=>{await api(`${base}/submissions/${s.id}/grade`,{method:'PUT',body:{adjustments:s.members.map(m=>({studentId:m.id,score:m.score===''?null:m.score,reason:m.reason||''})),publish,score:s.score,feedback:s.feedback,expectedVersion:s.version}});await load(s.id);notice.value=publish?'已發布成績與評語。':'評分草稿已儲存。'})}
function guard(){return !(editing.value||file.value||gradeDirty.value)||confirm('有未儲存的作業設定、成績或尚未繳交的檔案，確定離開？')}
onBeforeRouteLeave(guard);onBeforeRouteUpdate(guard)
function unload(event){if(editing.value||file.value||gradeDirty.value){event.preventDefault();event.returnValue=''}}
window.addEventListener('beforeunload',unload);onBeforeUnmount(()=>window.removeEventListener('beforeunload',unload))
onMounted(()=>run(load))
</script>
<template><RouterLink :to="report?{path:`/courses/${report.courseId}`,query:{section:'assessments'}}:'/courses'" class="back-link">← 返回測驗與作業</RouterLink><p v-if="error" class="error-box" role="alert">{{error}}</p><p v-if="notice" class="success-box" role="status">{{notice}}</p><template v-if="report"><section class="page-heading"><div><p class="eyebrow">PDF REPORT ASSIGNMENT</p><h1>{{report.title}}</h1><p class="muted">{{report.submissionMode==='group'?'小組 PDF 作業':'個人 PDF 作業'}} · 人工閱讀與給分 · 滿分 {{report.maxScore}} · 權重 {{report.weight}}</p></div><span class="status-badge">{{{draft:'草稿',published:'已發布',closed:'已關閉'}[report.status]}}</span></section><section class="surface form-surface"><h2>作業說明</h2><p class="studio-prose">{{report.instructions}}</p><p>開放 {{formatDate(report.opensAt)}} · 截止 {{formatDate(report.dueAt)}}</p><div v-if="staff&&!selectedCourse?.taRestrictions?.includes('assessments')" class="studio-actions"><button v-if="report.status==='draft'" class="button secondary" :disabled="busy" @click="edit">編輯作業草稿</button><button v-if="report.status==='draft'" class="button primary" :disabled="busy || editing" @click="transition('publish')">發布 PDF 作業</button><button v-if="report.status==='published'" class="button secondary" :disabled="busy" @click="transition('close')">關閉繳交</button></div></section><section v-if="editing" class="surface form-surface"><form @submit.prevent="save"><ReportModeFields :form="form" :course="report.courseId"/><label>作業名稱<input v-model="form.title" required maxlength="200" /></label><label>作業說明<textarea v-model="form.instructions" rows="5" maxlength="24000"></textarea></label><label>滿分<input v-model.number="form.maxScore" type="number" min="0.01" max="999999" step="0.01" required /></label><label>開放時間<input v-model="form.opensAt" type="datetime-local" /></label><label>截止時間<input v-model="form.dueAt" type="datetime-local" /></label><label><input type="checkbox" v-model="form.notifyStudents"/>發布時通知學生</label><p class="field-hint">權重請在「課程成績」調整。</p><button class="button primary" :disabled="busy">儲存作業草稿</button><button type="button" class="button secondary" @click="editing=false">取消</button></form></section><section v-if="!staff && !report.isPractice && ((!submissions.length && (report.submissionMode==='individual' || roster.some(r=>r.canSubmit))) || submissions.some(s=>s.canResubmit))" class="surface form-surface"><h2>繳交 PDF 報告</h2><p v-if="report?.isPractice" class="submission-notice">學生體驗提交本人的練習報告，不納入正式成績。切回教學視角可從獨立練習紀錄評分。</p><form @submit.prevent="submit"><label>PDF 報告（最多 20 MB）<input type="file" accept=".pdf,application/pdf" required :disabled="busy || (report.status!=='published' && !submissions.some(s=>s.canResubmit))" @change="file=$event.target.files[0]" /></label><p class="field-hint">繳交後會保留版本。教師退回後可以重新繳交。</p><button class="button primary" :disabled="busy || !file || (report.status!=='published' && !submissions.some(s=>s.canResubmit))">繳交 PDF 報告</button></form></section><section v-if="roster.length" class="surface form-surface"><h2>繳交總覽</h2><p v-for="(r,i) in roster" :key="i">{{r.name}} · {{r.submitted?(r.late?'逾期繳交':'已繳交'):(report.dueAt && Date.parse(report.dueAt)<=Date.now()?'逾期未繳':'未繳交')}}</p></section><section class="surface form-surface"><h2><FilePenLine v-if="staff" :size="20" />{{staff?'作業評閱與給分':'我的繳交與成績'}}</h2><article v-for="s in submissions" :key="s.id" class="question-editor"><h3>{{s.studentNumber}} {{s.studentName}}</h3><p v-if="s.members.length">{{s.members.map(m=>m.name+(m.isLeader?'（組長）':'')).join('、')}}</p><p v-for="h in s.history" :key="h.revision">第 {{h.revision}} 版 · {{h.submittedBy}} · {{h.fileName}} · {{formatDate(h.submittedAt)}} <button class="button secondary" @click="download(s,h)">下載第 {{h.revision}} 版</button></p><p>第 {{s.revision}} 版 · {{s.submittedBy}} 上傳並繳交 · {{s.returned?'退回修改':'正式繳交'}} · {{s.fileName}} · {{formatDate(s.submittedAt)}}</p><FilePreview :endpoint="`${base}/submissions/${s.id}/preview`" :file-name="s.fileName" content-type="application/pdf" /><button class="button secondary" :disabled="busy" @click="download(s)">下載／閱讀 PDF</button><ReportEvaluation v-if="report.evaluationMode!=='off' && s.members.length && (!staff || !selectedCourse?.taRestrictions?.includes('grading'))" :base="base" :submission="s" :report="report" :staff="staff"/>
<button v-if="staff && !selectedCourse?.taRestrictions?.includes('grading') && !s.returned && s.publishedScore==null" class="button secondary" @click="returnFile(s)">退回修改</button>
<form v-if="!s.returned && staff&&!selectedCourse?.taRestrictions?.includes('grading')" @submit.prevent="grade(s,$event.submitter?.value==='publish')"><label>{{s.members.length?'小組基礎成績':'作業得分'}}<input v-model.number="s.score" type="number" min="0" :max="report.maxScore" step="0.01" required /></label><fieldset v-for="m in s.members" :key="m.id"><legend>{{m.name}}</legend><label>個別成績（留白採小組分數）<input type="number" min="0" :max="report.maxScore" step="0.01" v-model.number="m.score"></label><label>調整原因<input v-model="m.reason" :required="m.score!=null && m.score!==''" maxlength="500"></label><p>已發布：{{m.publishedScore??'未發布'}}</p></fieldset><label>教師評語<textarea v-model="s.feedback" maxlength="16000" rows="3"></textarea></label><button class="button primary" :disabled="busy">儲存評分草稿</button><button value="publish" class="button primary" :disabled="busy">發布成績</button><p>已發布得分：{{s.publishedScore??'未發布'}}</p></form><div v-else><p>得分：{{s.score??'待評分'}} / {{report.maxScore}}</p><p class="studio-prose">{{s.feedback}}</p></div></article><p v-if="!submissions.length" class="empty-inline">目前沒有可見的繳交紀錄。</p></section><RouterLink :to="{path:`/courses/${report.courseId}`,query:{section:'grades'}}" class="button secondary">查看課程成績</RouterLink></template></template>
